/**
 * Unit tests for TokenBuffer.writeNumber(double d).
 */
public class TokenBuffer_writeNumber_TriageGen0Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Initialize TokenBuffer with a codec to allow serialization/parsing verification
        tokenBuffer = new TokenBuffer(mapper);
    }















    @Test
    public void testWriteNumber_Sequence() throws IOException {
        // Test that multiple calls append correctly
        tokenBuffer.writeNumber(1.1);
        tokenBuffer.writeNumber(2.2);

        JsonParser parser = tokenBuffer.asParser();

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(1.1, parser.getDoubleValue(), 0.0001);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, parser.nextToken());
        assertEquals(2.2, parser.getDoubleValue(), 0.0001);
    }
}
